package com.library.server.controller; import com.library.common.constant.RoleConstant; import com.library.common.annotation.RequireRole; import com.library.common.model.*; import com.library.pojo.entity.Admin; import com.library.server.service.AdminService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admins") @RequireRole(RoleConstant.ADMIN) public class AdminController {private final AdminService service;public AdminController(AdminService service){this.service=service;} @GetMapping public ApiResult<PageResult<Admin>> page(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int size,@RequestParam(required=false) String keyword){return ApiResult.success(service.page(keyword,page,size));} @PostMapping public ApiResult<Void> save(@RequestBody Admin x){service.save(x);return ApiResult.success();} @PutMapping public ApiResult<Void> update(@RequestBody Admin x){service.update(x);return ApiResult.success();} @DeleteMapping("/{id}") public ApiResult<Void> delete(@PathVariable Long id){service.delete(id);return ApiResult.success();}}
